/** A URL slug for a title. */
export function slugify(title) {
  const words = title
    .normalize("NFD")
    .replace(/\p{M}/gu, "")
    .toLowerCase()
    .match(/[a-z0-9]+/g) ?? [];
  let slug = "";

  for (const word of words) {
    const candidate = slug ? `${slug}-${word}` : word;
    if (candidate.length > 40) break;
    slug = candidate;
  }

  return slug;
}
